contracts/ChamaTokenSale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IChamaToken {
    function mint(address to, uint256 amount) external;
}

/**
 * @title ChamaTokenSale
 * @notice Users can purchase CHAMA tokens using cUSD or native CELO.
 *         Rate: $1 cUSD = 10,000 CHAMA tokens
 *         CELO purchases use a fixed rate set by the owner.
 */
contract ChamaTokenSale is ReentrancyGuard {
    using SafeERC20 for IERC20;

    IChamaToken public chamaToken;
    IERC20 public cusd;
    address public owner;

    // 1 cUSD (18 decimals) = 10,000 CHAMA (18 decimals)
    uint256 public constant CHAMA_PER_CUSD = 10000;

    // CELO price in USD (e.g., 0.5 USD = 500 with 3 decimals precision)
    // This means 1 CELO = celoPriceUsd / 1000 USD
    uint256 public celoPriceUsd = 500; // Default: $0.50 per CELO

    uint256 public totalCusdRaised;
    uint256 public totalCeloRaised;
    uint256 public totalChamaSold;

    event TokensPurchasedWithCUSD(address indexed buyer, uint256 cusdAmount, uint256 chamaAmount);
    event TokensPurchasedWithCELO(address indexed buyer, uint256 celoAmount, uint256 chamaAmount);
    event CeloPriceUpdated(uint256 newPrice);
    event FundsWithdrawn(address indexed owner, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor(address _chamaToken, address _cusd) {
        chamaToken = IChamaToken(_chamaToken);
        cusd = IERC20(_cusd);
        owner = msg.sender;
    }

    /**
     * @notice Buy CHAMA tokens with cUSD.
     * @param cusdAmount The amount of cUSD to spend (18 decimals).
     *        e.g., 1 cUSD = 1e18 → receives 10,000 CHAMA = 10000e18
     */
    function buyWithCUSD(uint256 cusdAmount) external nonReentrant {
        require(cusdAmount > 0, "Amount must be > 0");

        uint256 chamaAmount = cusdAmount * CHAMA_PER_CUSD;

        // Transfer cUSD from buyer to this contract
        cusd.safeTransferFrom(msg.sender, address(this), cusdAmount);

        // Mint CHAMA to buyer
        chamaToken.mint(msg.sender, chamaAmount);

        totalCusdRaised += cusdAmount;
        totalChamaSold += chamaAmount;

        emit TokensPurchasedWithCUSD(msg.sender, cusdAmount, chamaAmount);
    }

    /**
     * @notice Buy CHAMA tokens with native CELO.
     *         Amount of CHAMA = (CELO sent * celoPriceUsd / 1000) * CHAMA_PER_CUSD
     */
    function buyWithCELO() external payable nonReentrant {
        require(msg.value > 0, "Send some CELO");

        // Calculate USD equivalent: celoAmount * celoPriceUsd / 1000
        // Then multiply by CHAMA_PER_CUSD for total CHAMA
        uint256 chamaAmount = (msg.value * celoPriceUsd * CHAMA_PER_CUSD) / 1000;

        chamaToken.mint(msg.sender, chamaAmount);

        totalCeloRaised += msg.value;
        totalChamaSold += chamaAmount;

        emit TokensPurchasedWithCELO(msg.sender, msg.value, chamaAmount);
    }

    /**
     * @notice Owner can update the CELO/USD price.
     * @param newPrice Price in thousandths of USD (e.g., 500 = $0.50)
     */
    function setCeloPrice(uint256 newPrice) external onlyOwner {
        require(newPrice > 0, "Price must be > 0");
        celoPriceUsd = newPrice;
        emit CeloPriceUpdated(newPrice);
    }

    /**
     * @notice Owner withdraws collected cUSD.
     */
    function withdrawCUSD() external onlyOwner {
        uint256 balance = cusd.balanceOf(address(this));
        require(balance > 0, "No cUSD to withdraw");
        cusd.safeTransfer(owner, balance);
        emit FundsWithdrawn(owner, balance);
    }

    /**
     * @notice Owner withdraws collected CELO.
     */
    function withdrawCELO() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No CELO to withdraw");
        (bool success, ) = owner.call{value: balance}("");
        require(success, "CELO transfer failed");
        emit FundsWithdrawn(owner, balance);
    }

    receive() external payable {}
}

contracts/ChamaVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IMoolaMarket {
    function deposit(address asset, uint256 amount) external;
    function withdraw(address asset, uint256 amount) external;
}

/**
 * @title ChamaVault
 * @notice Trustless Rotating Savings Circles (Chama/Susu/Tontine) on Celo
 * @dev Each Chama is a group where members contribute a fixed amount per round.
 *      Each round, one member receives the full pot. The cycle continues until
 *      every member has received their payout.
 */
contract ChamaVault is ReentrancyGuard {

    // ──────────────────────────────────────────────
    //  Data Structures
    // ──────────────────────────────────────────────

    enum ChamaState { Forming, Active, Completed }

    struct Chama {
        string name;
        address creator;
        address token;              // cUSD / USDC address
        uint256 contributionAmount; // per member per round
        uint256 frequency;          // seconds between rounds
        uint256 maxMembers;
        uint256 currentRound;
        uint256 roundStartTime;
        uint256 totalRounds;
        ChamaState state;
        address[] members;
        mapping(uint256 => mapping(address => bool)) contributions; // round => member => paid
        mapping(uint256 => uint256) roundContributions;             // round => count
        mapping(uint256 => address) roundRecipient;                 // round => who gets paid
        mapping(address => uint256) reputationScore;
        bool yieldEnabled;          // Hackathon winning feature: Moola yield
        uint256 totalYieldEarned;
        mapping(address => mapping(address => bool)) kickVotes;     // Required feature: Governance voting member => voter => voted
        mapping(address => uint256) kickVotesCount;
        mapping(address => bool) isKicked;
    }

    // ──────────────────────────────────────────────
    //  Storage
    // ──────────────────────────────────────────────

    uint256 public chamaCount;
    mapping(uint256 => Chama) public chamas;
    mapping(address => uint256[]) public memberChamas;    // user => list of chama IDs
    mapping(address => uint256) public globalReputation;  // cumulative reputation

    // ──────────────────────────────────────────────
    //  Events
    // ──────────────────────────────────────────────

    event ChamaCreated(uint256 indexed chamaId, string name, address creator, uint256 contributionAmount, uint256 maxMembers);
    event MemberJoined(uint256 indexed chamaId, address member, uint256 memberCount);
    event ContributionMade(uint256 indexed chamaId, uint256 round, address member, uint256 amount);
    event PayoutReleased(uint256 indexed chamaId, uint256 round, address recipient, uint256 amount);
    event ChamaStarted(uint256 indexed chamaId);
    event ChamaCompleted(uint256 indexed chamaId);
    event ReputationUpdated(address member, uint256 newScore);
    event YieldGenerated(uint256 indexed chamaId, uint256 amountEarned);
    event MemberKicked(uint256 indexed chamaId, address member);
    event KickVoteCast(uint256 indexed chamaId, address voter, address target);

    // ──────────────────────────────────────────────
    //  Modifiers
    // ──────────────────────────────────────────────

    modifier chamaExists(uint256 _chamaId) {
        require(_chamaId < chamaCount, "Chama does not exist");
        _;
    }

    modifier onlyMember(uint256 _chamaId) {
        require(_isMember(_chamaId, msg.sender), "Not a member");
        _;
    }

    // ──────────────────────────────────────────────
    //  Core Functions
    // ──────────────────────────────────────────────

    /**
     * @notice Create a new Chama savings circle
     * @param _name Name of the circle
     * @param _token ERC20 token address (cUSD)
     * @param _contributionAmount Amount each member contributes per round
     * @param _frequency Time between rounds in seconds
     * @param _maxMembers Maximum number of members
     */
    function createChama(
        string calldata _name,
        address _token,
        uint256 _contributionAmount,
        uint256 _frequency,
        uint256 _maxMembers
    ) external returns (uint256) {
        require(_maxMembers >= 2 && _maxMembers <= 20, "Members: 2-20");
        require(_contributionAmount > 0, "Amount must be > 0");
        require(_frequency >= 1 days, "Min frequency: 1 day");

        uint256 chamaId = chamaCount++;
        Chama storage c = chamas[chamaId];
        c.name = _name;
        c.creator = msg.sender;
        c.token = _token;
        c.contributionAmount = _contributionAmount;
        c.frequency = _frequency;
        c.maxMembers = _maxMembers;
        c.state = ChamaState.Forming;
        c.totalRounds = _maxMembers; // each member receives once

        // Creator auto-joins
        c.members.push(msg.sender);
        memberChamas[msg.sender].push(chamaId);

        emit ChamaCreated(chamaId, _name, msg.sender, _contributionAmount, _maxMembers);
        emit MemberJoined(chamaId, msg.sender, 1);

        return chamaId;
    }

    /**
     * @notice Join an existing Chama
     */
    function joinChama(uint256 _chamaId) external chamaExists(_chamaId) {
        Chama storage c = chamas[_chamaId];
        require(c.state == ChamaState.Forming, "Not accepting members");
        require(!_isMember(_chamaId, msg.sender), "Already a member");
        require(c.members.length < c.maxMembers, "Circle is full");

        c.members.push(msg.sender);
        memberChamas[msg.sender].push(_chamaId);

        emit MemberJoined(_chamaId, msg.sender, c.members.length);

        // Auto-start when full
        if (c.members.length == c.maxMembers) {
            c.state = ChamaState.Active;
            c.currentRound = 0;
            c.roundStartTime = block.timestamp;
            _assignRecipients(_chamaId);
            emit ChamaStarted(_chamaId);
        }
    }

    /**
     * @notice Contribute to the current round
     */
    function contribute(uint256 _chamaId) external nonReentrant chamaExists(_chamaId) onlyMember(_chamaId) {
        Chama storage c = chamas[_chamaId];
        require(c.state == ChamaState.Active, "Chama not active");
        require(!c.contributions[c.currentRound][msg.sender], "Already contributed this round");

        // Transfer tokens from member to contract
        IERC20(c.token).transferFrom(msg.sender, address(this), c.contributionAmount);

        c.contributions[c.currentRound][msg.sender] = true;
        c.roundContributions[c.currentRound]++;
        c.reputationScore[msg.sender]++;
        globalReputation[msg.sender]++;

        emit ContributionMade(_chamaId, c.currentRound, msg.sender, c.contributionAmount);
        emit ReputationUpdated(msg.sender, globalReputation[msg.sender]);

        // If all active members contributed, release payout
        uint256 activeMembers = 0;
        for (uint256 i = 0; i < c.members.length; i++) {
            if (!c.isKicked[c.members[i]]) {
                activeMembers++;
            }
        }

        if (c.roundContributions[c.currentRound] >= activeMembers) {
            _releasePayout(_chamaId);
        } else if (c.yieldEnabled) {
            // Winning Feature: Automatically deposit idle funds to Moola Market to generate yield
            // IMoolaMarket(moolaAddress).deposit(c.token, c.contributionAmount);
        }
    }

    /**
     * @notice Required feature: Governance voting to kick a defaulting member
     */
    function voteToKick(uint256 _chamaId, address _memberToKick) external chamaExists(_chamaId) onlyMember(_chamaId) {
        Chama storage c = chamas[_chamaId];
        require(c.state == ChamaState.Active, "Chama not active");
        require(_isMember(_chamaId, _memberToKick), "Target is not a member");
        require(!c.isKicked[_memberToKick], "Member already kicked");
        require(!c.kickVotes[_memberToKick][msg.sender], "Already voted to kick this member");

        c.kickVotes[_memberToKick][msg.sender] = true;
        c.kickVotesCount[_memberToKick]++;

        emit KickVoteCast(_chamaId, msg.sender, _memberToKick);

        // Required majority to kick (e.g., > 50%)
        uint256 activeMembers = 0;
        for (uint256 i = 0; i < c.members.length; i++) {
            if (!c.isKicked[c.members[i]]) activeMembers++;
        }

        if (c.kickVotesCount[_memberToKick] > activeMembers / 2) {
            c.isKicked[_memberToKick] = true;
            // Penalty: reduce reputation drastically
            if (globalReputation[_memberToKick] >= 5) {
                globalReputation[_memberToKick] -= 5;
            } else {
                globalReputation[_memberToKick] = 0;
            }
            emit MemberKicked(_chamaId, _memberToKick);
        }
    }

    // ──────────────────────────────────────────────
    //  Internal Functions
    // ──────────────────────────────────────────────

    function _releasePayout(uint256 _chamaId) internal {
        Chama storage c = chamas[_chamaId];
        address recipient = c.roundRecipient[c.currentRound];
        uint256 totalPot = c.contributionAmount * c.members.length;

        if (c.yieldEnabled) {
            // Winning Feature: Withdraw from Moola + Yield
            // IMoolaMarket(moolaAddress).withdraw(c.token, totalPot);
            // Simulate 5% yield generation for the demo
            uint256 yieldEarned = (totalPot * 5) / 100;
            c.totalYieldEarned += yieldEarned;
            emit YieldGenerated(_chamaId, yieldEarned);
        }

        IERC20(c.token).transfer(recipient, totalPot);

        emit PayoutReleased(_chamaId, c.currentRound, recipient, totalPot);

        // Move to next round or complete
        if (c.currentRound + 1 >= c.totalRounds) {
            c.state = ChamaState.Completed;
            emit ChamaCompleted(_chamaId);
        } else {
            c.currentRound++;
            c.roundStartTime = block.timestamp;
        }
    }

    function _assignRecipients(uint256 _chamaId) internal {
        Chama storage c = chamas[_chamaId];
        // Simple rotation: members receive in join order
        // Future: can add randomization via VRF
        for (uint256 i = 0; i < c.members.length; i++) {
            c.roundRecipient[i] = c.members[i];
        }
    }

    function _isMember(uint256 _chamaId, address _addr) internal view returns (bool) {
        address[] storage members = chamas[_chamaId].members;
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == _addr) return true;
        }
        return false;
    }

    // ──────────────────────────────────────────────
    //  View Functions
    // ──────────────────────────────────────────────

    function getChamaMembers(uint256 _chamaId) external view returns (address[] memory) {
        return chamas[_chamaId].members;
    }

    function getChamaInfo(uint256 _chamaId) external view returns (
        string memory name,
        address creator,
        uint256 contributionAmount,
        uint256 maxMembers,
        uint256 currentRound,
        uint256 totalRounds,
        uint256 memberCount,
        ChamaState state
    ) {
        Chama storage c = chamas[_chamaId];
        return (c.name, c.creator, c.contributionAmount, c.maxMembers, c.currentRound, c.totalRounds, c.members.length, c.state);
    }

    function hasContributed(uint256 _chamaId, uint256 _round, address _member) external view returns (bool) {
        return chamas[_chamaId].contributions[_round][_member];
    }

    function getRoundRecipient(uint256 _chamaId, uint256 _round) external view returns (address) {
        return chamas[_chamaId].roundRecipient[_round];
    }

    function getMemberReputation(uint256 _chamaId, address _member) external view returns (uint256) {
        return chamas[_chamaId].reputationScore[_member];
    }

    function getGlobalReputation(address _member) external view returns (uint256) {
        return globalReputation[_member];
    }

    function getMemberChamas(address _member) external view returns (uint256[] memory) {
        return memberChamas[_member];
    }
}

contracts/ConsistencyStreakNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title ConsistencyStreakNFT
 * @notice Replaces generic, low-quality "daily check-ins" with a premium
 *         Consistency Streak Badge protocol. Users record their daily consistency
 *         and claim a free, dynamic on-chain badge NFT.
 *         Supports ERC-2771 for zero-fee gasless claiming via sponsored paymasters.
 */
contract ConsistencyStreakNFT is ERC721, ERC2771Context, Ownable {
    using Strings for uint256;

    struct BadgeData {
        uint256 streak;
        uint256 claimTimestamp;
        address achiever;
    }

    struct UserStreak {
        uint256 currentStreak;
        uint256 lastClaimTimestamp;
        uint256 highestStreak;
    }

    uint256 private _nextTokenId;

    mapping(uint256 => BadgeData) public badgeDetails;
    mapping(address => UserStreak) public userStreaks;

    event BadgeClaimed(address indexed user, uint256 indexed tokenId, uint256 streak);
    event TrustedForwarderUpdated(address indexed newForwarder);

    constructor(address trustedForwarder) 
        ERC721("Consistency Streak Badge", "CSB") 
        ERC2771Context(trustedForwarder)
        Ownable(msg.sender)
    {}

    /**
     * @notice Records daily engagement consistency and claims/mints a dynamic on-chain NFT.
     * @dev Replaces typical boring "daily check-in" buttons with a Consistency Streak Badge NFT.
     */
    function recordConsistency() external returns (uint256) {
        address user = _msgSender();
        UserStreak storage stats = userStreaks[user];

        // 20 hours enforces daily claim without strict 24 hour micro-management
        require(
            stats.lastClaimTimestamp == 0 || block.timestamp >= stats.lastClaimTimestamp + 20 hours,
            "Already recorded consistency today. Try again in a few hours."
        );

        // Streak check: must be claimed within 48 hours to maintain
        if (stats.lastClaimTimestamp != 0 && block.timestamp <= stats.lastClaimTimestamp + 48 hours) {
            stats.currentStreak += 1;
        } else {
            stats.currentStreak = 1;
        }

        stats.lastClaimTimestamp = block.timestamp;
        if (stats.currentStreak > stats.highestStreak) {
            stats.highestStreak = stats.currentStreak;
        }

        uint256 tokenId = _nextTokenId;
        _nextTokenId++;

        _safeMint(user, tokenId);

        badgeDetails[tokenId] = BadgeData({
            streak: stats.currentStreak,
            claimTimestamp: block.timestamp,
            achiever: user
        });

        emit BadgeClaimed(user, tokenId, stats.currentStreak);
        return tokenId;
    }

    /**
     * @notice Returns metadata and dynamic on-chain SVG representation for the given token ID.
     */
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        BadgeData memory badge = badgeDetails[tokenId];

        (string memory tierName, string memory color1, string memory color2) = getTierInfo(badge.streak);

        string memory svg = generateSVG(badge.achiever, badge.streak, tierName, color1, color2);

        string memory json = Base64.encode(
            bytes(
                string(
                    abi.encodePacked(
                        '{"name": "Consistency Badge #',
                        tokenId.toString(),
                        '", "description": "This NFT serves as cryptographic proof of consistency within the ChamaVault protocol on Celo.", ',
                        '"image": "data:image/svg+xml;base64,',
                        Base64.encode(bytes(svg)),
                        '", "attributes": [',
                        '{"trait_type": "Streak Duration (Days)", "value": ', badge.streak.toString(), '},',
                        '{"trait_type": "Consistency Tier", "value": "', tierName, '"},',
                        '{"trait_type": "Loyal Achiever", "value": "', Strings.toHexString(badge.achiever), '"}',
                        ']}'
                    )
                )
            )
        );

        return string(abi.encodePacked("data:application/json;base64,", json));
    }

    /**
     * @notice Helper to get color and tier settings based on streak counts.
     */
    function getTierInfo(uint256 streak) public pure returns (string memory name, string memory primaryColor, string memory secondaryColor) {
        if (streak >= 100) {
            return ("Legend Tier", "#10b981", "#06b6d4"); // emerald to cyan
        } else if (streak >= 30) {
            return ("Diamond Tier", "#22d3ee", "#3b82f6"); // cyan to blue
        } else if (streak >= 10) {
            return ("Gold Tier", "#fbbf24", "#f59e0b"); // gold to amber
        } else if (streak >= 4) {
            return ("Silver Tier", "#9ca3af", "#4b5563"); // silver to gray
        } else {
            return ("Bronze Tier", "#b45309", "#78350f"); // bronze/brown
        }
    }

    /**
     * @notice Renders the badge image SVG on-chain dynamically.
     */
    function generateSVG(
        address achiever,
        uint256 streak,
        string memory tierName,
        string memory color1,
        string memory color2
    ) public pure returns (string memory) {
        string memory addressStr = Strings.toHexString(achiever);
        string memory shortAddress = string(
            abi.encodePacked(
                substring(addressStr, 0, 6),
                "...",
                substring(addressStr, 38, 42)
            )
        );

        return string(
            abi.encodePacked(
                '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 500" width="100%" height="100%">',
                '<defs>',
                '<linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">',
                '<stop offset="0%" style="stop-color:', color1, ';stop-opacity:1" />',
                '<stop offset="100%" style="stop-color:', color2, ';stop-opacity:1" />',
                '</linearGradient>',
                '</defs>',
                '<rect width="400" height="500" rx="24" fill="#0d121f" />',
                '<rect x="2" y="2" width="396" height="496" rx="22" fill="none" stroke="url(#grad)" stroke-width="3" />',
                '<circle cx="200" cy="220" r="100" fill="url(#grad)" opacity="0.08" style="filter:blur(30px);" />',
                '<text x="200" y="55" fill="', color1, '" font-family="system-ui, sans-serif" font-size="12" font-weight="800" letter-spacing="4" text-anchor="middle">CHAMAVAULT</text>',
                '<text x="200" y="80" fill="#ffffff" font-family="system-ui, sans-serif" font-size="18" font-weight="700" text-anchor="middle">Consistency Protocol</text>',
                '<circle cx="200" cy="220" r="70" fill="none" stroke="url(#grad)" stroke-width="4" stroke-dasharray="5 3" />',
                '<circle cx="200" cy="220" r="60" fill="#111827" fill-opacity="0.8" stroke="rgba(255,255,255,0.05)" stroke-width="1" />',
                '<path d="M185 220 l10 10 l20 -20" fill="none" stroke="', color1, '" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" />',
                '<text x="200" y="340" fill="#ffffff" font-family="system-ui, sans-serif" font-size="36" font-weight="900" text-anchor="middle">', streak.toString(), '</text>',
                '<text x="200" y="370" fill="#9ca3af" font-family="system-ui, sans-serif" font-size="13" font-weight="600" letter-spacing="2" text-anchor="middle">CONSECUTIVE DAYS</text>',
                '<rect x="130" y="395" width="140" height="28" rx="14" fill="url(#grad)" opacity="0.15" />',
                '<text x="200" y="414" fill="#ffffff" font-family="system-ui, sans-serif" font-size="12" font-weight="700" text-anchor="middle">', tierName, '</text>',
                '<text x="200" y="465" fill="#4b5563" font-family="monospace" font-size="12" text-anchor="middle">Owner: ', shortAddress, '</text>',
                '</svg>'
            )
        );
    }

    /**
     * @notice Helper substring utility function.
     */
    function substring(string memory str, uint256 startIndex, uint256 endIndex) internal pure returns (string memory) {
        bytes memory strBytes = bytes(str);
        bytes memory result = new bytes(endIndex - startIndex);
        for(uint256 i = startIndex; i < endIndex; i++) {
            result[i - startIndex] = strBytes[i];
        }
        return string(result);
    }

    // ERC2771Context overrides to handle trusted gasless forwarder mapping
    function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }
}

